马上关掉我的浏览器会话，不占你的浏览器。

[tool-call run_code] {"timeoutMs": 120000, "code": "
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const r = await tools.pwsh({ command: `$env:AGENT_BROWSER_SESSION_NAME='money-research'
'--- close my session ---'
agent-browser close 2>&1 | Out-String
'--- remaining chrome procs ---'
Get-Process chrome -ErrorAction SilentlyContinue | Measure-Object | ForEach-Object { "chrome procs: " + $_.Count }`, description: "Close my browser session and free the browser", timeoutMs: 100000, workdir: "C:\\Users\\jjq21" });
console.log(t(r).slice(0, 2000));
", "description": "Close my browser session to free the user's browser"}

